56	\section{Games and strategies}
57	% Paper subsection label sec:strat kept for cross-reference fidelity.
58	\label{sec:strat}
59	
60	\begin{definition}[Two-player one-round games]\label{def:game}
61		A \emph{two-player one-round game} $\mathfrak G$ is specified by a tuple $(\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ where
62		\begin{enumerate}
63			\item $\mathcal X$ and $\mathcal Y$ are finite sets, called the \emph{question alphabets},
64			\item $\mathcal A$ and $\mathcal B$ are finite sets, called the \emph{answer alphabets},
65			\item $\mu$ is a probability distribution over $\mathcal X \times \mathcal Y$, called the \emph{question distribution}, and
66			\item $D \colon \mathcal X \times \mathcal Y \times \mathcal A \times \mathcal B \to \{0,1\}$ is a function, called the \emph{decision predicate}.
67		\end{enumerate}
68	\end{definition}
